CREATE SCHEMA auth;
CREATE SCHEMA app_private;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE TABLE public.workspaces(id uuid PRIMARY KEY);
CREATE TABLE public.workspace_members(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES public.workspaces(id), user_id uuid NOT NULL REFERENCES auth.users(id), status text NOT NULL, role text NOT NULL DEFAULT 'operator', UNIQUE(id, workspace_id));
CREATE TABLE public.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, recipient_id uuid NOT NULL, conversation_id uuid, type text NOT NULL);
